import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import os from 'node:os';
import {inventory} from '../../../scripts/bundle/inventory.mjs';import {enforce,classify} from '../../../scripts/bundle/measurement.mjs';
test('Given conditional CSS points to an absent legacy font; When measuring; Then report an unresolved cost rather than inventing zero bytes',t=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'css-cost-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));fs.writeFileSync(root+'/index.html','<link rel="stylesheet" href="s.css">');fs.writeFileSync(root+'/a.js','a');fs.writeFileSync(root+'/s.css','@font-face{src:url(missing.eot)}');const r=inventory(root,{graph:{a:{file:'a.js',isEntry:true}},emitted:['index.html','a.js'],publicFiles:['s.css']});assert.deepEqual(r.unresolvedCss,['missing.eot']);assert.ok(!r.initialFiles.includes('missing.eot'));});
test('Given inherited property names; When graph imports name a nonexistent node; Then no prototype value counts as a node',()=>assert.throws(()=>classify({app:{file:'a.js',isEntry:true,imports:['toString']}},'app'),/Missing import/));
test('Given a failed build report; When comparing budgets; Then refuse it even if its numeric fields look valid',()=>{const keys='schemaVersion graphSemantics assetPolicy gzip node zlib vite mode configHash lockHash scenario browserCache buildCache'.split(' ');const metadata=Object.fromEntries(keys.map(k=>[k,'same']));assert.throws(()=>enforce({passed:false,metadata,metrics:{x:1}},{passed:true,metadata,metrics:{x:1}},{x:{absolute:0,relative:0}}),/failed/i)});
